import json

def compute_temporal_concentration(events):
    annual_data = {}

    for e in events:
        year = e['entry_time'][:4]
        if year not in annual_data:
            annual_data[year] = {'n_trades': 0, 'net_pnl_sum': 0.0, 'positive_trades': 0}

        annual_data[year]['n_trades'] += 1
        annual_data[year]['net_pnl_sum'] += e['net_pnl']
        if e['net_pnl'] > 0:
            annual_data[year]['positive_trades'] += 1

    result = {
        'years_with_positive_net': sum(1 for year in annual_data if annual_data[year]['net_pnl_sum'] > 0),
        'years_total_with_at_least_1_trade': len(annual_data),
        **{year: {
            'n_trades': data['n_trades'],
            'net_pnl_sum': data['net_pnl_sum'],
            'win_rate': data['positive_trades'] / data['n_trades'] if data['n_trades'] > 0 else 0.0
        } for year, data in annual_data.items()}
    }

    return result
